$errors = 0;
echo "<span class=\"info\">[START] Memulai penulisan file ke backend SkipperHost...</span><br>";

foreach ($files as $relPath => $base64) {
    $targetPath = $baseDir . "/" . $relPath;
    $targetDir  = dirname($targetPath);

    if (!is_dir($targetDir)) {
        @mkdir($targetDir, 0755, true);
    }

    $content = base64_decode($base64);
    $bytes = @file_put_contents($targetPath, $content);

    if ($bytes !== false) {
        echo "<span class=\"success\">[OK] {$relPath}</span> (" . number_format($bytes) . " bytes berhasil di-patch)<br>";
    } else {
        $errors++;
        echo "<span class=\"error\">[FAIL] Gagal menulis ke {$relPath}! Periksa permission folder.</span><br>";
    }
}

echo "<br><span class=\"info\">[CACHE] Membersihkan bootstrap cache & compile file...</span><br>";

$cacheFiles = [
    $baseDir . "/bootstrap/cache/config.php",
    $baseDir . "/bootstrap/cache/services.php",
    $baseDir . "/bootstrap/cache/packages.php",
    $baseDir . "/bootstrap/cache/routes-v7.php",
];

foreach ($cacheFiles as $cf) {
    if (file_exists($cf)) {
        if (@unlink($cf)) {
            echo "<span class=\"success\">[PURGED] " . basename($cf) . "</span><br>";
        } else {
            echo "<span class=\"warn\">[SKIP] Tidak bisa menghapus " . basename($cf) . "</span><br>";
        }
    } else {
        echo "<span class=\"info\">[CLEAN] " . basename($cf) . " (sudah bersih)</span><br>";
    }
}

// Artisan clear jika bootstrap tersedia
if (file_exists($baseDir . "/bootstrap/app.php")) {
    try {
        require_once $baseDir . "/bootstrap/app.php";
        if (class_exists('Illuminate\Support\Facades\Artisan')) {
            \Illuminate\Support\Facades\Artisan::call('config:clear');
            \Illuminate\Support\Facades\Artisan::call('cache:clear');
            echo "<span class=\"success\">[ARTISAN] config:clear & cache:clear berhasil dieksekusi.</span><br>";
        }
    } catch (\Throwable $e) {
        echo "<span class=\"warn\">[NOTE] Artisan call skipped: " . htmlspecialchars($e->getMessage()) . "</span><br>";
    }
}

echo "<br>";
if ($errors === 0) {
    echo "<span class=\"success\" style=\"font-weight:bold; font-size:1.05rem;\">&#10004; SEMUA FILE TELAH BERHASIL DI-PATCH DENGAN SUKSES!</span><br>";
} else {
